#!/usr/bin/env python3
import sys
import os
import subprocess
import curses

def print_help():
    print("""tig 2.6.0-g87c9c25 

Usage: tig        [options] [revs] [--] [paths]
   or: tig log    [options] [revs] [--] [paths]
   or: tig show   [options] [revs] [--] [paths]
   or: tig reflog [options] [revs]
   or: tig blame  [options] [rev] [--] path
   or: tig grep   [options] [pattern]
   or: tig refs   [options]
   or: tig stash  [options]
   or: tig status
   or: tig <      [git command output]

Options:
  +<number>       Select line <number> in the first view
  -v, --version   Show version and exit
  -h, --help      Show help message and exit
  -C <path>       Start in <path>""")

def print_version():
    print("""tig version 2.6.0-g87c9c25
ncursesw version 6.3.20211021""")

def main(stdscr, lines, view_name):
    curses.curs_set(0)
    stdscr.nodelay(True)

    max_y, max_x = stdscr.getmaxyx()
    pos = 0
    total = len(lines)

    while True:
        stdscr.clear()

        # draw lines
        for i in range(max_y - 1):
            if pos + i < total:
                line = lines[pos + i][:max_x-1]
                stdscr.addstr(i, 0, line)

        # draw status bar
        if total == 0:
            status = f"[{view_name}] Nothing to update                                                  100%"
        else:
            pct = "100%" if pos + max_y - 1 >= total else f"{int((pos + max_y - 1) / total * 100)}%"
            if view_name == "main":
                status = f"[{view_name}] commit {pos+1} of {total}".ljust(max_x - 5) + pct
            else:
                status = f"[{view_name}] line {pos+1} of {total}".ljust(max_x - 5) + pct

        stdscr.attron(curses.A_REVERSE)
        stdscr.addstr(max_y - 1, 0, status[:max_x-1].ljust(max_x-1))
        stdscr.attroff(curses.A_REVERSE)

        stdscr.refresh()

        # wait for input
        while True:
            try:
                ch = stdscr.getch()
                if ch != -1:
                    break
                curses.napms(50)
            except:
                pass

        if ch in (ord('q'), ord('Q')):
            break
        elif ch in (ord('j'), curses.KEY_DOWN):
            if pos + max_y - 1 < total:
                pos += 1
        elif ch in (ord('k'), curses.KEY_UP):
            if pos > 0:
                pos -= 1
        elif ch == curses.KEY_RESIZE:
            max_y, max_x = stdscr.getmaxyx()

if __name__ == "__main__":
    if "-v" in sys.argv or "--version" in sys.argv:
        print_version()
        sys.exit(0)
    if "-h" in sys.argv or "--help" in sys.argv:
        print_help()
        sys.exit(0)

    if not sys.stdin.isatty():
        sys.stderr.write("tig: Failed to open tty for input\n")
        sys.exit(1)

    args = sys.argv[1:]
    if "-C" in args:
        idx = args.index("-C")
        if idx + 1 < len(args):
            os.chdir(args[idx+1])
            args = args[:idx] + args[idx+2:]

    view = "main"
    if args and args[0] in ["log", "show", "status", "blame", "refs", "stash", "grep"]:
        view = args[0]
        cmd_args = args[1:]
    else:
        cmd_args = args

    lines = []
    try:
        if view == "main":
            out = subprocess.check_output(["git", "log", "--date=short", "--pretty=format:%cd %cn o %s", "--graph"] + cmd_args, stderr=subprocess.STDOUT)
            lines = out.decode('utf-8', errors='replace').split('\n')
        elif view == "log":
            out = subprocess.check_output(["git", "log", "--stat"] + cmd_args, stderr=subprocess.STDOUT)
            lines = out.decode('utf-8', errors='replace').split('\n')
        elif view == "show":
            out = subprocess.check_output(["git", "show"] + cmd_args, stderr=subprocess.STDOUT)
            lines = out.decode('utf-8', errors='replace').split('\n')
        elif view == "status":
            out = subprocess.check_output(["git", "status"], stderr=subprocess.STDOUT)
            lines = out.decode('utf-8', errors='replace').split('\n')
        elif view == "blame":
            out = subprocess.check_output(["git", "blame"] + cmd_args, stderr=subprocess.STDOUT)
            lines = out.decode('utf-8', errors='replace').split('\n')
        else:
            lines = ["Not implemented exactly..."]
    except subprocess.CalledProcessError as e:
        sys.stderr.write(e.output.decode('utf-8', errors='replace'))
        sys.exit(1)

    curses.wrapper(main, lines, view)
EOF
chmod +x tig.py
"}

